<template>
  <div>
    <el-form label-width="130px" style="width:60%">
      <el-form-item label="系统版本：">
        {{ sysInfo.version || "--" }}
      </el-form-item>
      <el-form-item label="设备序列号：">
        {{ sysInfo.serial_number || "--" }}
      </el-form-item>
      <el-form-item label="开放令牌：">
        <div style="word-break: break-all;">{{ foreverToken || "--" }}</div> 
      </el-form-item>
      <el-form-item label="剩余天数：">
        <span
          class="f-bold fs-18"
          :style="{ color: sysInfo.remaining_days <= 10 ? 'red' : '#67C23A' }"
        >
          {{ sysInfo.remaining_days }} </span
        >天
        <el-button
          class="ml-10"
          type="text"
          v-if="sysInfo.remaining_days <= 10"
          @click="goAuthorize"
          >去授权</el-button
        >
      </el-form-item>
    </el-form>
    <Authorize :isAuthorize="isAuthorize" @close="close" v-if="isAuthorize" />
  </div>
</template>

<script>
import Authorize from "@/components/authorize";

export default {
  components: {
    Authorize,
  },
  data() {
    return {
      sysInfo: {},
      isAuthorize: false,
      foreverToken: "",
    };
  },
  created() {
    this.foreverToken = localStorage.getItem("ForeverToken");
    this.getSysInfo();
  },
  methods: {
    getSysInfo() {
      this.$api.get(`/sys/getSysInfo`).then((res) => {
        if (res.data.data) {
          this.sysInfo = res.data.data;
        }
      });
    },

    goAuthorize() {
      this.isAuthorize = true;
    },
    close() {
      this.isAuthorize = false;
    },
  },
};
</script>

<style></style>
